/// <summary>
/// MPJ_28155_SalesFinalisation Controller class for route update feature
/// </summary>
class METSalesOrderShipmentWorkbenchRouteUpdateController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METSalesOrderShipmentWorkbenchRouteUpdateController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false); 

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METSalesOrderShipmentWorkbenchRouteUpdateService), methodstr(METSalesOrderShipmentWorkbenchRouteUpdateService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>Main method</summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METSalesOrderShipmentWorkbenchRouteUpdateContract    dataContract;
        METSalesOrderShipmentWorkbenchRouteUpdateController  controller;
        FormRun                                     formRun;
        FormDataSource                              salesTable_ds;
        MultiSelectionHelper                        helper;
        SalesTable                                  salesTable;
        CustAccount                                 custAcc;
        int                                         recordCount = 1;
        container                                   salesOrderShipCon;
        formRun                                = _args.caller();

        salesTable_ds    = formRun.dataSource(formDataSourceStr(METSalesOrderShipmentWorkbench, salesTable));
        helper                                 = MultiSelectionHelper::construct();
        helper.parmDataSource(salesTable_ds);

        salesTable       = helper.getfirst();
        custAcc = salesTable.CustAccount;
        while (salesTable)
        {
            if(custAcc != salesTable.CustAccount && recordCount > 1 )
            {
                throw Error("@MET:SalesWorkbenchOrderNotUpdate");
            }
            salesOrderShipCon     = conIns(salesOrderShipCon, conLen(salesOrderShipCon) + 1, salesTable.SalesId);
            salesTable   = helper.getNext();
            recordCount++;
        }

        if(conLen(salesOrderShipCon))
        {
            controller              = METSalesOrderShipmentWorkbenchRouteUpdateController::construct(_args);
            dataContract            = controller.getDataContractObject();
            dataContract.parmSalesOrderList(salesOrderShipCon);
            dataContract.parmPrimaryRoute(salesTable.METRoute);
            dataContract.parmRouteStop(salesTable.METRouteStopNum);
            controller.startOperation();
        }
        else
        {
            warning("@MET:NoSalesOrderToProcess");
        }
    }

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "@MET:UpdateRoutes";
}
